const corpo = $json;
const itens = Array.isArray(corpo?.data) ? corpo.data
            : Array.isArray(corpo) ? corpo
            : (() => { throw new Error('Envelope inesperado de eaps: ' + JSON.stringify(corpo).slice(0, 300)); })();
return itens.map(t => ({ json: { card_id: Number(t.id), id_obra: Number(t.id_obra) } }));

// TODO: mapeamento de campos AINDA NÃO CONFIRMADO -- escrito às cegas,
// sem ter visto uma resposta real do endpoint 'avancos'. Ajustar os
// nomes à ESQUERDA (fonte.<campo>) assim que tivermos uma amostra real;
// os nomes à DIREITA já são as colunas reais de
// `eap_apontamentos`/`eap_tarefas` no MySQL (migration 008_eap.sql).
//
// Assumindo que a resposta é 1 objeto (não lista), já que a URL pede um
// card_id + data específicos. Se vier vazio/null, é dia sem apontamento
// -- pula sem gravar nada (não é erro), devolvendo lista vazia.

const fonte = $json;
if (!fonte || (Array.isArray(fonte) && !fonte.length)) return [];
const a = Array.isArray(fonte) ? fonte[0] : fonte;

const cardOriginal = $('Loop tarefas (1 por vez)').item.json;
const dataHoje = $('Data de hoje').item.json.data_hoje;

// 1 objeto só -- a rota /ingest/eap/avanco-diario grava em eap_apontamentos
// (campos de apontamento) E atualiza o snapshot em eap_tarefas (campos de
// progresso) a partir do MESMO objeto.
const item = {
  tarefa_id: cardOriginal.card_id,
  id_eap_grupo: a.id_eap != null ? Number(a.id_eap) : null,
  nome_eap: a.nome_eap,
  nome_obra: a.nome_obra,
  data_do_input: dataHoje,
  edt: a.edt,
  tarefa: a.tarefa,
  qtd: a.qtd,
  unidade: a.unidade,
  avanco_atual: a.avanco_atual,
  avanco_atual_p100: a.avanco_atual_p100,
  avanco_diario: a.avanco_diario,
  usuario_avanco_diario: a.usuario_avanco_diario,
  uuid_origem: a.uuid || a.UUID,
  meta_diaria: a.meta_diaria,
  status_qualidade: a.status_qualidade,
  desvio: a.desvio,
  hht_consumido: a.hht_consumido,
};

return [{ json: { item } }];
